using System;
using System.Linq;
using System.Text.Json.Nodes;

// 以导出的真实原版状态和规则为夹具，不依赖Godot节点或绘制。
public static class NativeVerification
{
    public static void Run(JsonObject source)
    {
        int passed=0;
        JsonObject Fixture(){var result=new JsonObject();foreach(string key in new[]{"version","snapshot","rules","terrain","zones","portals"})result[key]=source[key]!.DeepClone();return result;}
        void Check(bool condition,string message){if(!condition)throw new Exception("RULE_TEST_FAILED: "+message);}
        void Test(string name,Action<NativeGame,JsonObject> body){var root=Fixture();var game=new NativeGame(root);body(game,root);game.Validate();passed++;Godot.GD.Print("RULE_OK "+name);}
        Test("feed_and_inventory",(g,r)=>{var p=g.Pets[0]!;int stock=g.Stock("普通饲料");p["hunger"]=20;g.Execute("feed",new JsonObject{{"pet_id",NativeGame.S(p,"pet_id")}});Check(g.Stock("普通饲料")==stock-1&&NativeGame.D(p,"hunger")==50,"饲料扣除/饥饿回复");});
        Test("atomic_failure",(g,r)=>{g.Meta["coins"]=0;string before=g.State.ToJsonString();try{g.Execute("buy",new JsonObject{{"item","高级饲料"},{"quantity",5}});throw new Exception("未拒绝不足金币");}catch(InvalidOperationException){}Check(g.State.ToJsonString()==before,"失败后完整回滚");});
        Test("save_failure",(g,r)=>{string before=g.State.ToJsonString();try{g.Execute("buy",new JsonObject{{"item","清水"}},()=>throw new System.IO.IOException("模拟磁盘失败"));}catch(System.IO.IOException){}Check(g.State.ToJsonString()==before,"保存失败回滚");});
        Test("shop_price",(g,r)=>{int coins=NativeGame.I(g.Meta,"coins"),stock=g.Stock("清水");g.Execute("buy",new JsonObject{{"item","清水"},{"quantity",5}});Check(NativeGame.I(g.Meta,"coins")==coins-10&&g.Stock("清水")==stock+5,"原版清水定价");});
        Test("pet_decay",(g,r)=>{g.Commons["enabled"]=false;var p=g.Pets[0]!;double hunger=NativeGame.D(p,"hunger");g.Advance(3600);Check(NativeGame.D(p,"hunger")<hunger&&NativeGame.D(p,"last_update_ts")==g.Now,"真实时间衰减");});
        Test("foster_pause",(g,r)=>{g.Commons["enabled"]=false;var p=g.Pets[0]!;p["fostered"]=true;double hunger=NativeGame.D(p,"hunger");g.Advance(7200);Check(NativeGame.D(p,"hunger")==hunger&&NativeGame.D(p,"paused_seconds")==7200,"寄养暂停属性和年龄");});
        Test("family_growth_and_tasks",(g,r)=>{g.Advance(30*86400);Check(NativeGame.I(g.Commons,"completed")>0,"自治完成生产");Check(NativeGame.I(g.Commons,"births")>0,"家庭新增人口");Check(g.Rows("town_buildings").Any(b=>!NativeGame.B(b!,"starter_home")),"人口增长后实际新建住宅，不把初始安置房当成施工成果");Check(g.People.Count(p=>NativeGame.S(p!,"role")=="居民")>4,"居民增长");});
        Test("autonomy_pause",(g,r)=>{g.Advance(3600);int count=g.People.Count(p=>NativeGame.S(p!,"role")=="居民");g.Execute("autonomy",new JsonObject());Check(g.Jobs.Count==0,"预约工作取消");g.Advance(86400);Check(g.People.Count(p=>NativeGame.S(p!,"role")=="居民")==count,"暂停不填满居民人口");});
        Test("offspring",(g,r)=>{g.Commons["enabled"]=false;g.Rules["CONCEPTION_CHANCE"]=1;foreach(var p in g.Pets){p!["birth_ts"]=g.Now-NativeGame.D(p,"lifespan_max")*.4;p["favor"]=60;p["illness_budget"]=1000;}int count=g.Pets.Count;g.Execute("breed",new JsonObject{{"pet_id",NativeGame.S(g.Pets[0]!,"pet_id")},{"mate_id",NativeGame.S(g.Pets[1]!,"pet_id")}});g.Advance(86400);Check(g.Pets.Count==count+1,"宠物幼崽实际出生");});
        Test("offline_incremental_equivalence",(g,r)=>{var copy=Fixture();copy["snapshot"]=g.State.DeepClone();var other=new NativeGame(copy);g.Advance(2*86400);for(int i=0;i<48;i++)other.Advance(3600);Check(g.Commons.ToJsonString()==other.Commons.ToJsonString(),"离线与逐小时公共状态一致");});
        Test("order_reward",(g,r)=>{var order=g.Rows("orders").First(o=>NativeGame.S(o!,"kind")=="item")!;int need=NativeGame.I(order,"quantity"),coins=NativeGame.I(g.Meta,"coins");g.Add(NativeGame.S(order,"item"),need);g.Execute("order",new JsonObject{{"order_id",NativeGame.S(order,"order_id")}});Check(NativeGame.I(g.Meta,"coins")==coins+NativeGame.I(order,"reward"),"原订单奖励");});
        Test("sanitation_emit",(g,r)=>{g.Commons["enabled"]=false;g.Advance(6*3600);Check(g.Rows("waste").Count>0,"宠物定时排泄");int count=g.Rows("waste").Sum(w=>NativeGame.I(w!,"quantity"));g.Execute("clean_waste",new JsonObject());Check(g.Rows("waste").Count==0&&g.Stock("粪便")==count,"清扫入库数量守恒");});
        Test("sanitation_atomic_capacity",(g,r)=>{g.Rows("waste").Add(new JsonObject{{"waste_id","test"},{"building_id",0},{"quantity",1},{"created_ts",g.Now}});g.Rows("inventory").Clear();g.Add("清水",g.Storage);string before=g.State.ToJsonString();try{g.Execute("clean_waste",new JsonObject());throw new Exception("仓满未拒绝");}catch(InvalidOperationException){}Check(g.State.ToJsonString()==before,"仓满不丢失粪便");});
        Test("manager_work_and_wage",(g,r)=>{g.Commons["enabled"]=false;g.Execute("farm_manager",new JsonObject());g.Advance(6*3600+60);Check(NativeGame.I(g.Meta,"manager_cleaned")>0&&g.Stock("粪便")>0,"管理员按任务收集并入库");Check(NativeGame.D(g.Meta,"manager_next_wage_ts")>g.Now,"工资定时结算");});
        Test("stale_waste_exposure",(g,r)=>{g.Rows("waste").Add(new JsonObject{{"waste_id","stale"},{"building_id",0},{"quantity",3},{"created_ts",g.Now-86400}});var exposure=g.Exposure(0);Check(exposure.Stale==3&&exposure.Hazard>1&&exposure.Dirt>0,"陈旧粪便影响脏污和疾病");});
        Test("order_refresh",(g,r)=>{g.Commons["enabled"]=false;g.Advance(86400);Check(g.Rows("orders").Count>3&&g.Rows("orders").Any(o=>NativeGame.D(o!,"created_ts")==g.Now),"每日刷新真实订单");});
        Test("event_effect_and_timeout",(g,r)=>{g.Commons["enabled"]=false;foreach(var visitor in g.People.Where(p=>NativeGame.S(p!,"role")=="游客"))visitor!["spent"]=true;foreach(string key in new[]{"next_visitor_ts","next_rent_ts","next_tax_ts"})g.Meta[key]=g.Now+NativeGame.Day;var e=new JsonObject{{"event_id","test"},{"kind","tourists"},{"text","测试庆典"},{"options",new JsonArray("布置","自然接待")},{"expiry_ts",g.Now+3600},{"status","待处理"}};g.Rows("events").Clear();g.Rows("events").Add(e);int coins=NativeGame.I(g.Meta,"coins");g.Advance(3600);Check(NativeGame.S(e,"status")=="过期"&&NativeGame.I(g.Meta,"coins")==coins+40,"超时执行第二选项且只结算一次");});
        Test("event_discount_price",(g,r)=>{g.Rows("events").Add(new JsonObject{{"event_id","merchant-test"},{"kind","merchant"},{"text","商人"},{"options",new JsonArray("欢迎","婉拒")},{"expiry_ts",g.Now+3600},{"status","待处理"}});int price=g.BuyPrice("高级饲料");g.Execute("event",new JsonObject{{"event_id","merchant-test"},{"option",0}});Check(g.BuyPrice("高级饲料")<price,"折扣作用于实际价格");});
        Test("pet_order_departure",(g,r)=>{var pet=g.Pets[0]!;var order=g.Rows("orders").First(o=>NativeGame.S(o!,"kind")=="pet")!;order["species"]=NativeGame.S(pet,"species");order["stage"]=g.Stage(pet);g.Execute("order",new JsonObject{{"order_id",NativeGame.S(order,"order_id")},{"pet_id",NativeGame.S(pet,"pet_id")}});Check(!g.Active(pet)&&NativeGame.S(order,"status")=="完成","交付宠物真实离园");});
        Test("building_capacity_growth",(g,r)=>{var home=g.Rows("buildings").First(b=>NativeGame.S(b!,"kind")=="饲养小屋")!;int level=NativeGame.I(home,"level");int cost=(int)(NativeGame.I(g.Rules["BUILDINGS"]!["饲养小屋"]!,"cost")*level*NativeGame.D(g.Rules,"UPGRADE_PRICE_FACTOR")),coins=NativeGame.I(g.Meta,"coins");g.Execute("upgrade_manor",new JsonObject{{"building_id",NativeGame.I(home,"building_id")}});Check(NativeGame.I(g.Meta,"coins")==coins-cost&&NativeGame.I(home,"level")==level+1,"升级按原版等级计费");});
        Test("achievement_once",(g,r)=>{var p=g.Pets[0]!;p["favor"]=80;g.Execute("rename",new JsonObject{{"pet_id",NativeGame.S(p,"pet_id")},{"name","星星"}});Check(g.State["achievements"]!["friends"]!=null,"达成成就");int coins=NativeGame.I(g.Meta,"coins");g.Execute("rename",new JsonObject{{"pet_id",NativeGame.S(p,"pet_id")},{"name","星星二号"}});Check(NativeGame.I(g.Meta,"coins")==coins,"成就不重复领取");});
        Test("foster_no_excretion",(g,r)=>{g.Commons["enabled"]=false;g.Rows("waste").Clear();foreach(var p in g.Pets)p!["fostered"]=true;g.Advance(86400);Check(g.Rows("waste").Count==0,"寄养暂停排泄计时");});
        Test("snapshot_reload_continuity",(g,r)=>{g.Advance(3600);var copy=Fixture();copy["snapshot"]=g.State.DeepClone();var restored=new NativeGame(copy);g.Advance(3600);restored.Advance(3600);Check(g.State.ToJsonString()==restored.State.ToJsonString(),"保存恢复后生产/家庭/随机与时钟连续");});
        void Open(NativeGame g){foreach(var zone in g.Rows("town_zones"))zone!["level"]=3;g.Meta["coins"]=50000;}
        NativeGame.Cell BuildCell(NativeGame g,string key,int rotation=0){for(int y=0;y<80;y++)for(int x=0;x<125;x++)if(g.PlacementReason(key,x,y,rotation)=="")return new(x,y);throw new Exception("测试地图没有可用临街选址");}
        Test("road_edit_undo",(g,r)=>{Open(g);var c=BuildCell(g,"cream_home");int coins=NativeGame.I(g.Meta,"coins"),count=g.Rows("roads").Count;g.Execute("road",new JsonObject{{"cx",c.X},{"cy",c.Y},{"style","stone"}});Check(g.Rows("roads").Count==count+1&&NativeGame.I(g.Meta,"coins")==coins-14,"道路按风格实际扣款");g.Execute("undo_road",new JsonObject());Check(g.Rows("roads").Count==count&&NativeGame.I(g.Meta,"coins")==coins,"撤销恢复道路与金币");});
        Test("road_remove_refund_no_repeat",(g,r)=>{Open(g);var c=BuildCell(g,"cream_home");g.Execute("road",new JsonObject{{"cx",c.X},{"cy",c.Y}});int coins=NativeGame.I(g.Meta,"coins");g.Execute("remove_road",new JsonObject{{"cx",c.X},{"cy",c.Y}});Check(NativeGame.I(g.Meta,"coins")==coins+5,"拆路退一半已付费用");g.Execute("undo_road",new JsonObject());Check(NativeGame.I(g.Meta,"coins")==coins,"撤销退款需归还");try{g.Execute("undo_road",new JsonObject());throw new Exception("重复撤销未拒绝");}catch(InvalidOperationException){} });
        Test("rotated_construction_and_removal",(g,r)=>{Open(g);var c=BuildCell(g,"bus_stop",1);g.Execute("build_town",new JsonObject{{"catalog_key","bus_stop"},{"cx",c.X},{"cy",c.Y},{"orientation",1}});var b=g.Rows("town_buildings").Last()!;Check(NativeGame.I(b,"w")==1&&NativeGame.I(b,"h")==2,"旋转后交换占地宽高");g.Execute("remove_town",new JsonObject{{"building_id",NativeGame.S(b,"building_id")}});Check(!g.Rows("town_buildings").Contains(b),"移除施工建筑");});
        Test("decoration_move_undo",(g,r)=>{Open(g);var c=BuildCell(g,"cream_home");g.Execute("decoration",new JsonObject{{"operation","place"},{"kind","bench"},{"cx",c.X},{"cy",c.Y}});var d=g.Meta["decorations"]!.AsArray().Last()!;string id=NativeGame.S(d,"id");g.Execute("decoration",new JsonObject{{"operation","move"},{"id",id},{"cx",c.X},{"cy",c.Y+1},{"orientation",2}});Check(NativeGame.I(g.Meta["decorations"]!.AsArray().Last()!,"cy")==c.Y+1,"装饰实际移动");g.Execute("decoration",new JsonObject{{"operation","undo"}});Check(NativeGame.I(g.Meta["decorations"]!.AsArray().Last()!,"cy")==c.Y,"撤销移动恢复位置");});
        Test("adoption_without_money",(g,r)=>{g.Meta["coins"]=0;int count=g.Pets.Count;g.Execute("adopt",new JsonObject());Check(g.Pets.Count==count+1,"经济困难时仍可公益领养");try{g.Execute("adopt",new JsonObject());throw new Exception("领养冷却未拒绝");}catch(InvalidOperationException){} });
        Test("protect_occupied_manor",(g,r)=>{int building=NativeGame.I(g.Pets[0]!,"building_id");string before=g.State.ToJsonString();try{g.Execute("demolish_manor",new JsonObject{{"building_id",building}});throw new Exception("有宠物建筑允许拆除");}catch(InvalidOperationException){}Check(g.State.ToJsonString()==before,"有宠物时拒绝拆除且完整回滚");});
        Test("natural_death_boundary",(g,r)=>{g.Commons["enabled"]=false;var p=g.Pets[0]!;double end=g.Now+300;p["birth_ts"]=end-NativeGame.D(p,"lifespan_max");p["illness_budget"]=1000;g.Advance(300);Check(!g.Active(p)&&NativeGame.S(p,"death_reason")=="寿终正寝"&&Math.Abs(NativeGame.D(p,"death_ts")-end)<.001,"寿命边界当次结算即离世");});
        Test("foster_product_expiry",(g,r)=>{g.Commons["enabled"]=false;var p=g.Pets[0]!;p["fostered"]=true;p["product_ready_ts"]=g.Now;p["product_expiry_ts"]=g.Now+300;g.Advance(600);Check(NativeGame.D(p,"product_ready_ts")==0,"寄养暂停年龄但已有产物仍按保质期消失");});
        Test("autonomous_field_harvest",(g,r)=>{Open(g);var c=g.Portal("fields");var estate=g.Portal("estate");g.Rows("roads").Clear();void Road(int x,int y){g.Rows("roads").Add(new JsonObject{{"road_id",$"{x},{y}"},{"cx",x},{"cy",y},{"road_style","asphalt"},{"built_ts",g.Now},{"paid",0}});}for(int x=Math.Min(c.X,estate.X);x<=Math.Max(c.X,estate.X);x++)Road(x,estate.Y);for(int y=Math.Min(c.Y,estate.Y);y<=Math.Max(c.Y,estate.Y);y++)if(y!=estate.Y)Road(c.X,y);g.Meta["field_ready_ts"]=g.Now;g.Meta["field_expiry_ts"]=g.Now+12*3600;g.Meta["field_batch"]=new JsonObject{{"谷物",2},{"鲜草",1}};int grain=g.Stock("谷物");g.Advance(4*3600);Check(g.Stock("谷物")==grain+2&&NativeGame.D(g.Meta,"field_ready_ts")==0,"居民自主将成熟作物收获入库");});
        passed+=NativeHousingVerification.Run(source);
        passed+=NativeFarmManagerVerification.Run(source);
        passed+=NativeUrbanVerification.Run(source);
        passed+=NativeFreightVerification.Run(source);
        Godot.GD.Print($"NATIVE_RULES_VERIFIED tests={passed}");
    }
}
